package org.eclipse.rdf4j.sail.lmdb;

import java.lang.management.ManagementFactory;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.BitSet;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.RepositoryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;

/** Retained fresh-store 20x1M campaign; smaller arguments exist only for harness/profiler smoke checks. */
public final class MatrixTwentyTransactionLoad {

	private static final String SUBJECT_PREFIX = "urn:lmdb:large-transaction:subject:";
	private static final String VALUE_PREFIX = "dictionary-value-for-large-transaction-";
	private static final String VALUE_SUFFIX = "-payload";
	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI[] PREDICATES = new IRI[4];
	private static final Resource[][] CONTEXTS = new Resource[8][1];

	static {
		for (int i = 0; i < PREDICATES.length; i++) {
			PREDICATES[i] = VF.createIRI("urn:lmdb:large-transaction:predicate:" + i);
		}
		for (int i = 1; i < CONTEXTS.length; i++) {
			CONTEXTS[i][0] = VF.createIRI("urn:lmdb:large-transaction:context:" + i);
		}
	}

	public static void main(String[] args) throws Exception {
		IsolationLevels isolation = IsolationLevels.valueOf(args[0]);
		int rows = Integer.parseInt(args[1]);
		int transactions = Integer.parseInt(args[2]);
		MatrixLoadSupport.require(rows > 0 && transactions > 0 && rows % transactions == 0, "balanced transactions");
		Path artifacts = Path.of(args[3]).toAbsolutePath();
		Files.createDirectories(artifacts);
		Path directory = artifacts.resolve("store");
		MatrixLoadSupport.require(!Files.exists(directory), "fresh retained store required");
		LmdbStoreConfig config = MatrixLoadSupport.config(1024L * 1024L, false);
		LmdbStore store = MatrixLoadSupport.store(directory, config, false);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			MatrixLoadSupport.verifyRuntime(store, config);
			long started;
			long elapsed;
			long addNanos = 0;
			long commitNanos = 0;
			long gcCount = gc(false);
			long gcMillis = gc(true);
			try (MatrixLoadSupport.Profile profile = new MatrixLoadSupport.Profile(artifacts);
					RepositoryConnection connection = repository.getConnection()) {
				started = System.nanoTime();
				for (int transaction = 0; transaction < transactions; transaction++) {
					connection.begin(isolation);
					long addStarted = System.nanoTime();
					int end = (transaction + 1) * (rows / transactions);
					for (int index = transaction * (rows / transactions); index < end; index++) {
						connection.add(VF.createIRI(SUBJECT_PREFIX + index), PREDICATES[index % PREDICATES.length],
								VF.createLiteral(VALUE_PREFIX + index + VALUE_SUFFIX),
								CONTEXTS[index % CONTEXTS.length]);
					}
					addNanos += System.nanoTime() - addStarted;
					long commitStarted = System.nanoTime();
					connection.commit();
					commitNanos += System.nanoTime() - commitStarted;
					System.out.println("public-commit=" + (transaction + 1) + " generated=" + end
							+ " elapsedSeconds=" + (System.nanoTime() - started) / 1e9);
				}
				elapsed = System.nanoTime() - started;
			}
			System.out.println("timing isolation=" + isolation + " rows=" + rows + " publicTransactions=" + transactions
					+ " elapsedSeconds=" + elapsed / 1e9 + " addSeconds=" + addNanos / 1e9
					+ " commitSeconds=" + commitNanos / 1e9 + " gcCount=" + (gc(false) - gcCount)
					+ " gcMillis=" + (gc(true) - gcMillis));
			verify(repository, rows, "committed");
			MatrixLoadSupport.verifyRuntime(store, config);
		} finally {
			repository.shutDown();
		}
		MatrixLoadSupport.verifyClosedIndexes(directory, rows);
		LmdbStore reopenedStore = MatrixLoadSupport.store(directory, config, false);
		SailRepository reopened = new SailRepository(reopenedStore);
		try {
			reopened.init();
			MatrixLoadSupport.verifyRuntime(reopenedStore, config);
			verify(reopened, rows, "reopened");
		} finally {
			reopened.shutDown();
		}
		System.out.println("campaign=PASS isolation=" + isolation + " rows=" + rows + " transactions=" + transactions);
	}

	private static long gc(boolean time) {
		return ManagementFactory.getGarbageCollectorMXBeans()
				.stream()
				.mapToLong(bean -> time ? bean.getCollectionTime() : bean.getCollectionCount())
				.filter(v -> v >= 0)
				.sum();
	}

	private static void verify(SailRepository repository, int rows, String phase) {
		BitSet seen = new BitSet(rows);
		int count = 0;
		try (RepositoryConnection connection = repository.getConnection();
				RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
			while (statements.hasNext()) {
				Statement statement = statements.next();
				String subject = statement.getSubject().stringValue();
				MatrixLoadSupport.require(statement.getSubject().isIRI() && subject.startsWith(SUBJECT_PREFIX),
						"unexpected subject " + subject);
				int index = Integer.parseInt(subject.substring(SUBJECT_PREFIX.length()));
				MatrixLoadSupport.require(index >= 0 && index < rows && subject.equals(SUBJECT_PREFIX + index),
						"subject outside exact lexical range " + subject);
				MatrixLoadSupport.require(!seen.get(index), "duplicate public subject " + subject);
				seen.set(index);
				MatrixLoadSupport.require(PREDICATES[index % PREDICATES.length].equals(statement.getPredicate()),
						"predicate " + subject);
				MatrixLoadSupport.require(statement.getObject() instanceof Literal, "literal object " + subject);
				Literal literal = (Literal) statement.getObject();
				MatrixLoadSupport.require(literal.getLabel().equals(VALUE_PREFIX + index + VALUE_SUFFIX)
						&& XSD.STRING.equals(literal.getDatatype()) && literal.getLanguage().isEmpty(),
						"literal lexical identity " + subject);
				Resource expectedContext = CONTEXTS[index % CONTEXTS.length][0];
				MatrixLoadSupport.require(expectedContext == null ? statement.getContext() == null
						: expectedContext.equals(statement.getContext()), "context " + subject);
				count++;
				if (count % 1_000_000 == 0) {
					System.out.println("validation-progress phase=" + phase + " checked=" + count);
				}
			}
		}
		MatrixLoadSupport.require(count == rows && seen.cardinality() == rows && seen.nextClearBit(0) == rows,
				"complete public cardinality and range " + count + "/" + rows);
		System.out.println("verified phase=" + phase + " allLexicalRows=" + count);
	}
}
